insert into public.equipment_models (slug, brand_id, model, category_id, specs, data_confidence, production_status)
select regexp_replace(trim(both '-' from regexp_replace(lower(translate(v.brand_id||' '||v.model,'ıİğĞüÜşŞöÖçÇ','iigguussoocc')),'[^a-z0-9]+','-','g')),'-+','-','g'),
       v.brand_id, v.model, 'montur', s.specs, 'inceleme-gerekli', 'bilinmiyor'
from v join s on s.code = v.code
where not exists (select 1 from public.equipment_models m where m.slug = regexp_replace(trim(both '-' from regexp_replace(lower(translate(v.brand_id||' '||v.model,'ıİğĞüÜşŞöÖçÇ','iigguussoocc')),'[^a-z0-9]+','-','g')),'-+','-','g'));